     3	/**
     4	 * Changes plan; refuses a downgrade that would breach a current quota.
     5	 *
     6	 * Owner D. The interesting case is the *downgrade*: the target plan's limits
     7	 * are compared against today's usage before the switch, so an org on growth
     8	 * with 40 seats cannot silently drop to starter and strand 37 people.
     9	 *
    10	 * Must call (do not reimplement): changePlanSchema, can, getPlanLimits,
    11	 * wouldExceedLimit, getActor, toActionResult
    12	 */
    13	
    14	import { ForbiddenActionError, PlanLimitError } from "@/actions/_lib/action-errors";
    15	import { withAction } from "@/actions/_lib/with-action";
    16	import { getPlanLimits, wouldExceedLimit } from "@/config/plan-limits";
    17	import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
    18	import { can } from "@/lib/permissions";
    19	import { changePlanSchema, type ChangePlanInput } from "@/schemas/billing";
    20	import { changePlan } from "@/server/services/billing-service";
    21	import { getUsage } from "@/server/services/usage-service";
    22	import type { ActionResult } from "@/types/api";
    23	import type { LimitedResource, Subscription } from "@/types/billing";
    24	import type { Actor } from "@/types/member";
    25	
    26	const run = withAction<typeof changePlanSchema, Subscription>(
    27	  changePlanSchema,
    28	  async (raw, actor) => {
    29	    const input = raw as ChangePlanInput;
    30	
    31	    if (!can(actor, "org:manage_billing", { kind: "billing", orgId: input.orgId })) {
    32	      throw new ForbiddenActionError("org:manage_billing");
    33	    }
    34	
    35	    await assertPlanFitsCurrentUsage(actor, input);
    36	
    37	    const subscription = await changePlan(actor, input);
    38	    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.hours);
    39	    return subscription;
    40	  },
    41	  { revalidate: ["billing"], cacheProfile: "hours" },
    42	);
    43	
    44	/**
    45	 * Compares live usage against the *target* plan. `wouldExceedLimit` is called
    46	 * with a requested delta of zero: we are not consuming anything, only asking
    47	 * whether what is already in use still fits.
    48	 */
    49	async function assertPlanFitsCurrentUsage(
    50	  actor: Actor,
    51	  input: ChangePlanInput,
    52	): Promise<void> {
    53	  const usage = await getUsage(actor, input.orgId);
    54	  const limits = getPlanLimits(input.plan);
    55	
    56	  const consumption: ReadonlyArray<readonly [LimitedResource, number]> = [
    57	    ["seats", usage.seatsUsed],
    58	    ["projects", usage.projectsUsed],
    59	    ["storageMb", usage.storageMbUsed],
    60	  ];
    61	
    62	  for (const [resource, used] of consumption) {
    63	    if (wouldExceedLimit(input.plan, resource, used, 0)) {
    64	      throw new PlanLimitError(resource, limits[resource], used);
    65	    }
    66	  }
    67	}
    68	
    69	export async function changePlanAction(raw: unknown): Promise<ActionResult<Subscription>> {
    70	  return run(raw);
    71	}
